sheet.css:
.pk{--paper:#fffdf6;--ink:#2b2b2b;--muted:#5f5b52;--red:#d92b1f;--yellow:#f5c518;--blue:#1f5fd9;
  --wob:255px 15px 225px 15px / 15px 225px 15px 255px;
  background:var(--paper);color:var(--ink);
  font:400 16px/1.6 ui-sans-serif,system-ui,-apple-system,sans-serif}
[data-theme=dark].pk,[data-theme=dark] .pk{--paper:#1e1c18;--ink:#f4f0e6;--muted:#b0a99c}
.stage.pk{--page:var(--paper);background:var(--paper)}
.pk h3,.pk h4{margin:0;font-weight:800;letter-spacing:-.02em;line-height:1.05}
.pk p{margin:0}
.muted{color:var(--muted)}
.hl{background:linear-gradient(transparent 62%,var(--yellow) 62%,var(--yellow) 92%,transparent 92%);
  padding:0 .1em}
.wob{border:2.5px solid var(--ink);border-radius:var(--wob);padding:18px;background:transparent}
.r1{transform:rotate(-1.4deg)}.r2{transform:rotate(1.1deg)}.r3{transform:rotate(-.6deg)}
.r4{transform:rotate(1.8deg)}
.mark{stroke:var(--red);stroke-width:2.5;fill:none;stroke-linecap:round}
.mark.b{stroke:var(--blue)}
.pk-btn{font:700 15px/1 inherit;background:transparent;color:var(--ink);border:2.5px solid var(--ink);
  border-radius:var(--wob);padding:12px 22px;cursor:pointer;transform:rotate(-1.5deg);
  transition:transform .14s}
.pk-btn:hover{transform:rotate(0deg)}
.pk-btn:focus-visible{outline:3px solid var(--blue);outline-offset:4px}
.pk-btn.pri{border-color:var(--red);color:var(--red)}
.pk-btn[disabled]{color:var(--muted);border-color:var(--muted);cursor:not-allowed;transform:none}
.f-hover{transform:rotate(0deg)!important}
.f-focus{outline:3px solid var(--blue);outline-offset:4px}
.pk-field{width:100%;background:transparent;color:var(--ink);border:2.5px solid var(--ink);
  border-radius:var(--wob);padding:11px 14px;font:400 16px/1.3 inherit;transform:rotate(.7deg)}
.pk-field:focus-visible{outline:3px solid var(--blue);outline-offset:4px}
.pk-label{display:block;font-weight:700;font-size:14px;margin-bottom:8px}
.pk-err{margin-top:9px;font-size:14px;font-weight:700;color:var(--red)}
.pk-nav{display:flex;gap:22px;align-items:baseline;flex-wrap:wrap}
.pk-nav a{color:var(--ink);text-decoration:none;font-weight:700;padding:6px 0;
  display:inline-block;min-height:26px}
.pk-nav a[aria-current]{background:linear-gradient(transparent 76%,var(--red) 76%,var(--red) 84%,transparent 84%)}
.pk-nav .sp{flex:1}
table.pk-t{width:100%;border-collapse:collapse;font-size:15px}
table.pk-t th{text-align:left;font-weight:800;padding:0 10px 10px 0;border-bottom:2.5px solid var(--ink)}
table.pk-t td{padding:12px 10px 12px 0;border-bottom:2px solid rgba(43,43,43,.28)}
[data-theme=dark] table.pk-t td{border-bottom-color:rgba(244,240,230,.3)}
.pk-scrim{background:rgba(43,43,43,.5);padding:36px 18px;display:flex;justify-content:center}
.pk-skel{height:13px;border-radius:99px;background:rgba(43,43,43,.14);margin-bottom:12px}
[data-theme=dark] .pk-skel{background:rgba(244,240,230,.16)}
.swatch{border:2.5px solid var(--ink,#2b2b2b);border-radius:var(--wob);height:54px}
